<?php
namespace App\Actions\Admissions;
use App\Models\{Applicant,AdmissionBill,FeeType}; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class GenerateAdmissionBillAction { public function execute(Applicant $applicant,FeeType $feeType,string $purpose='registration'): AdmissionBill { if(!in_array($applicant->status,['draft','submitted','selection_passed'],true)) throw ValidationException::withMessages(['status'=>'Pendaftar tidak dapat dibuatkan tagihan pada status ini.']); if(!$feeType->is_active) throw ValidationException::withMessages(['fee_type'=>'Jenis biaya tidak aktif.']); return DB::transaction(function()use($applicant,$feeType,$purpose){return AdmissionBill::firstOrCreate(['applicant_id'=>$applicant->id,'purpose'=>$purpose],['tenant_id'=>$applicant->tenant_id,'fee_type_id'=>$feeType->id,'bill_number'=>'PMB-'.now()->format('Ymd').'-'.Str::upper(Str::random(8)),'issued_at'=>now(),'due_date'=>now()->addDays(7),'amount'=>$feeType->default_amount,'paid_amount'=>0,'status'=>'unpaid']);}); } }
